//! Executable/tray assets are generated by `cargo run -p kit --example icons`.

#[cfg(test)]
mod tests {
    #[test]
    fn embedded_assets_match_the_shared_renderer() {
        for (name, state) in [
            ("screen-tools.ico", kit::icon::State::Normal),
            ("screen-tools.suspended.ico", kit::icon::State::Suspended),
            ("screen-tools.error.ico", kit::icon::State::Error),
            ("screen-tools.disabled.ico", kit::icon::State::Disabled),
        ] {
            let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
                .join("assets")
                .join(name);
            assert_eq!(
                std::fs::read(path).unwrap(),
                kit::icon::ico(kit::icon::SCREEN, state),
                "{name} is stale; regenerate the icon assets"
            );
        }
    }
}
